props.default:
(c: CommandPaletteCommand, q: string) => {
  const words = q.toLocaleLowerCase().split(/\s+/).filter(Boolean);
  if (!words.length) return true;
  const hay = [c.label, c.section ?? '', ...(c.keywords ?? [])].join(' ').toLocaleLowerCase();
  return words.every((w) => hay.includes(w));
}

(n: number, limit?: number) => {
      const cards = n === 1 ? '1 card' : `${n} cards`;
      if (limit == null) return cards;
      return n > limit ? `${n} of ${limit} cards, over the limit` : `${n} of ${limit} cards`;
    }
